import{_ as a}from"./chunks/telegram.B12pD7Cn.js";import{_ as r,o as t,c as o,a2 as l}from"./chunks/framework.DSc8fo6x.js";const h=JSON.parse('{"title":"Telegram: ежедневный отчёт и бэкап","description":"","frontmatter":{},"headers":[],"relativePath":"ru/telegram.md","filePath":"ru/telegram.md"}'),s={name:"ru/telegram.md"};function n(i,e,g,c,d,m){return t(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="telegram-ежедневныи-отчет-и-бэкап" tabindex="-1">Telegram: ежедневный отчёт и бэкап <a class="header-anchor" href="#telegram-ежедневныи-отчет-и-бэкап" aria-label="Permalink to &quot;Telegram: ежедневный отчёт и бэкап&quot;">​</a></h1><p>Каждый вечер на телефон владельца приходит краткий <strong>отчёт</strong> (продажи, выручка, наличные и карта, отмены — кто сделал, заканчивающиеся товары) и <strong>зашифрованный бэкап</strong>. Даже если компьютер украдут или он сломается, копия в Telegram останется.</p><p><strong>Если сообщение не пришло — это уже предупреждение:</strong> что-то не так.</p><h2 id="подключение-один-раз-нужен-интернет" tabindex="-1">Подключение (один раз, нужен интернет) <a class="header-anchor" href="#подключение-один-раз-нужен-интернет" aria-label="Permalink to &quot;Подключение (один раз, нужен интернет)&quot;">​</a></h2><ol><li>В Telegram на телефоне найдите <strong>@BotFather</strong> → <code>/newbot</code> → дайте боту название (напр. «Mağaza Kassa») и имя пользователя (должно заканчиваться на <code>bot</code>).</li><li>BotFather выдаст длинный <strong>токен</strong> (<code>123456789:AA…</code>). Скопируйте его.</li><li>Kassa → <strong>Настройки → Telegram</strong> → вставьте в поле <strong>Токен бота</strong>.</li><li>Найдите своего бота в Telegram и напишите ему <strong><code>/start</code></strong>. <ul><li><strong>Чтобы отправлять в группу:</strong> добавьте бота в группу и напишите в группе <strong><code>/start@имя_бота</code></strong> (напр. <code>/start@magaza_kassa_bot</code>). Обычного сообщения недостаточно — Telegram не показывает боту обычные сообщения группы.</li></ul></li><li>В Kassa нажмите <strong>Найти чат</strong>. Если найдено несколько чатов (личный и группа) — выберите из списка. Выбор <strong>сохраняется сам</strong>.</li><li>Выберите время отчёта (напр. 21:00) → <strong>Тестовое сообщение</strong>. На телефон должно прийти сообщение.</li></ol><p><img src="'+a+'" alt="Telegram"></p><h2 id="дальше" tabindex="-1">Дальше <a class="header-anchor" href="#дальше" aria-label="Permalink to &quot;Дальше&quot;">​</a></h2><ul><li>Отчёт приходит каждый день в выбранное время. Если программа была закрыта до этого времени — на следующий день приходит «запоздалый отчёт».</li><li>Бэкап — раз в день. При большой базе файл делится на части (<code>.001</code>, <code>.002</code>…).</li><li>Если интернета нет — повторная попытка каждые 15 минут. Время и результат последней отправки видны в Настройках.</li><li>Сохранённый токен на экране не показывается (поле пустое, написано «Сохранён»). Если кто-то узнал токен — <code>/revoke</code> в BotFather.</li></ul><div class="warning custom-block"><p class="custom-block-title">Жёлтое предупреждение «Бэкап в Telegram не отправляется»</p><p>Уже больше 2 дней ничего не удаётся отправить. Причина написана в предупреждении. Проверьте: есть интернет? Бот не удалён? Настройки → Telegram → <strong>Тестовое сообщение</strong>.</p></div><p>Как восстановить бэкап из Telegram: <a href="./backup.html#fayldan-berpa">Бэкап и восстановление</a>.</p>',10)])])}const u=r(s,[["render",n]]);export{h as __pageData,u as default};
